// HasIdentity applies the HasEdge predicate on the "identity" edge.
func HasIdentity() predicate.UserFederatedIdentity {
	return predicate.UserFederatedIdentity(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, true, IdentityTable, IdentityColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasIdentityWith applies the HasEdge predicate on the "identity" edge with a given conditions (other predicates).
func HasIdentityWith(preds ...predicate.UserIdentity) predicate.UserFederatedIdentity {
	return predicate.UserFederatedIdentity(func(s *sql.Selector) {
		step := newIdentityStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.UserFederatedIdentity) predicate.UserFederatedIdentity {
	return predicate.UserFederatedIdentity(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.UserFederatedIdentity) predicate.UserFederatedIdentity {
	return predicate.UserFederatedIdentity(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.UserFederatedIdentity) predicate.UserFederatedIdentity {
	return predicate.UserFederatedIdentity(sql.NotPredicates(p))
}
